var EXTRA=[{"dot": "gray", "j": "Bone Joint J", "h": "Editoriale sul trial RACER-Knee: protesi robotica contro convenzionale, il valore del robot", "v": "L'abstract non è disponibile su PubMed: il contenuto non è stato letto e il giudizio degli autori non è verificato.", "pmid": "42966373", "doi": "10.1302/0301-620X.108B11.BJJ-2026-1352", "temi": ["protesi robotica", "RACER-Knee", "VELYS", "editoriale"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Riparare il LCA: scegliere i legamenti giusti conta più della tecnica, scrive l'editoriale", "v": "Opinione senza dati propri: ricorda che giovane età e guaina sinoviale compromessa si associano a più fallimenti della riparazione; per l'autore la ricostruzione resta il riferimento.", "pmid": "42847898", "doi": "10.1002/arj.70687", "temi": ["riparazione primaria del LCA", "indicazioni", "editoriale"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Menisco laterale ipermobile: riparare e conservare, evitando di vincolare troppo lo iato popliteo", "v": "Editoriale (Super, Murray, LaPrade e colleghi): l'anatomia istologica da sola non giustifica la tecnica, la priorità è ripristinare l'anatomia nativa; opinione, senza dati.", "pmid": "42859895", "doi": "10.1002/arj.70655", "temi": ["menisco laterale", "iato popliteo", "riparazione", "editoriale"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Instabilità rotulea: la distanza tendine rotuleo-cresta trocleare può servire più della TT-TG", "v": "Editoriale sullo studio commentato: ricorda che displasia trocleare e altezza rotulea possono spiegare la differenza, se i gruppi non sono appaiati per anatomia.", "pmid": "42963902", "doi": "10.1002/arj.70747", "temi": ["instabilità rotulea", "TT-TG", "displasia trocleare", "editoriale"]}, {"dot": "gray", "j": "Knee Surg Sports Traumatol Arthrosc", "h": "LCA: il meccanismo da contatto si associa a lesioni strutturali più gravi alla risonanza e in artroscopia", "v": "Coorte retrospettiva su dati raccolti in prospettiva, con regressione aggiustata per età, sesso, BMI e intervallo; l'associazione sta in piedi dopo l'aggiustamento ma non è causale.", "pmid": "42931800", "doi": "10.1002/ksa.70660", "temi": ["LCA", "meccanismo di infortunio", "lesioni associate", "ACLISS"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Revisione del LCA in due tempi: l'allotrapianto di testa femorale riempie i tunnel, ma è un surrogato", "v": "Editoriale: il riempimento radiografico del tunnel non è un esito clinico; servono dati su fissazione e sopravvivenza dell'innesto.", "pmid": "42921761", "doi": "10.1002/arj.70699", "temi": ["revisione del LCA", "tunnel", "innesto osseo", "editoriale"]}, {"dot": "gray", "j": "Knee Surg Sports Traumatol Arthrosc", "h": "Metanalisi sul LCA con residuo conservato: una lettera ne contesta grafici e statistica", "v": "Lettera agli autori: segnala errori di riporto statistico e nei forest plot e propone un'analisi ricostruita; non porta nuovi pazienti.", "pmid": "42879145", "doi": "10.1002/ksa.70639", "temi": ["LCA", "residuo conservato", "metanalisi", "stabilità"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Rotula: ricostruzione di MPFL e legamento quadricipite-femorale in un gesto, con allograft", "v": "Nota tecnica senza pazienti: descrive il gesto con tensionamento dinamico, non ne misura l'esito; l'abstract non nomina il tipo di fissazione.", "pmid": "42960305", "doi": "10.1002/atn2.70386", "temi": ["MPFL", "instabilità rotulea", "nota tecnica"]}, {"dot": "gray", "j": "Asia Pac J Sports Med Arthrosc Rehabil Technol", "h": "Osteotomia tibiale aperta: la stabilità dinamica migliora, e l'instabilità preoperatoria la predice", "v": "Retrospettivo, un solo gruppo e pochi ginocchi, senza confronto; la stabilità è misurata con radioscopia da stress in sala.", "pmid": "42960013", "doi": "10.1016/j.asmart.2026.10.001", "temi": ["osteotomia", "stabilità dinamica", "slope"]}];
var SCOPERTE=[{"t": "Un microfono sulla curette: il suono dice quando il taglio passa dalla cartilagine all'osso calcificato", "v": "Prova di concetto del Mayo Clinic su resti di allotrapianti osteocondrali: il suono della sbrigliatura cambia di timbro quando la curette raggiunge lo strato calcificato, e il segnale distingue i due piani. Vale la deviazione per la preparazione del difetto prima di AMIC o ACI, che oggi si affida al tatto; è un banco con dodici preparazioni, non uno strumento in sala.", "pmid": "42954266", "doi": "10.1177/19476035261502886", "temi": ["bioingegneria", "preparazione del difetto", "cartilagine", "Mayo Clinic"]}, {"t": "Perché il menisco bianco non guarisce? Un modello matematico sul glucosio nella zona avascolare", "v": "Modello di diffusione, senza esperimenti né pazienti: stima che il glucosio non arrivi in quantità sufficienti a una lesione a 2,5 mm dalla zona vascolarizzata, e che una fonte sostenuta (uno scaffold) potrebbe cambiare il quadro. Gli autori dichiarano che non dimostra guarigione: vale la deviazione per vedere il menisco come problema di trasporto di nutrienti.", "pmid": "42959109", "doi": "10.3389/fbioe.2026.1880978", "temi": ["bioingegneria", "menisco", "zona bianca", "modello matematico"]}, {"t": "Come si cura il menisco discoide in Asia: sondaggio di 54 chirurghi contro il registro nordamericano", "v": "Dal mondo orientale: i chirurghi dell'Asia-Pacifico riparano più spesso del Nord America, soprattutto nelle lesioni intrasostanza e nell'instabilità del bordo. Vale la deviazione perché mostra come cambia la soglia di riparazione fra scuole; è pratica dichiarata in un sondaggio e non esito, e la saucerizzazione resta il gesto di base.", "pmid": "42964580", "doi": "10.1002/ars2.70155", "temi": ["mondo orientale", "menisco discoide", "riparazione", "sondaggio"]}];
var SOC={"2": {"video": "Per i difetti di cartilagine nel ginocchio con artrosi lieve o moderata si è confrontato un impianto di cellule staminali da sangue cordonale con ialuronato contro la microfrattura. A cinque anni, in 48 pazienti, il dolore e i punteggi funzionali erano più favorevoli con le staminali, e la cartilagine riparata si manteneva più spesso alla risonanza: 62,5% contro 26,3%.\n\nIl limite: analisi retrospettiva di un sottogruppo, con intervalli molto larghi; per la soglia di miglioramento minimo la differenza non è significativa. Il prodotto non è disponibile come scelta di routine.\nFonte: PubMed, PMID 42965407.", "linkedin": "Cartilagine, 5 anni (Arthroscopy, 2026): analisi retrospettiva di sottogruppo di uno studio di fase 3, ginocchia con artrosi Kellgren-Lawrence I-III; staminali mesenchimali allogeniche da sangue cordonale con ialuronato contro microfrattura, 48 pazienti al controllo finale su 89 dello studio originale. VAS 23,4 contro 46,3 (p = 0,0019); WOMAC 21,8 contro 37,7 (p = 0,016); IKDC 59,4 contro 46,5 (p = 0,014); riparazione durevole alla RM 62,5% contro 26,3% (OR 8,2, IC 95% 1,6-42,5).\n\nIl limite: retrospettivo, numero per braccio non riportato, soglia di miglioramento minimo non significativa (p da 0,074 a 0,123), comparatore la microfrattura semplice. Solo abstract.\nFonte: PubMed, PMID 42965407.", "instagram": "Cartilagine del ginocchio: staminali da sangue cordonale con ialuronato contro microfrattura.\n\nA cinque anni, in 48 pazienti, punteggi di dolore più bassi e riparazione più spesso conservata alla risonanza. Studio retrospettivo.\nFonte: PubMed, PMID 42965407.", "pazienti": "Quando la cartilagine del ginocchio è danneggiata, una tecnica chiamata microfrattura stimola il corpo a formare un nuovo tessuto di riparazione. Uno studio ha confrontato la microfrattura con un impianto di cellule staminali prese dal sangue del cordone ombelicale di donatori, insieme a un gel di acido ialuronico.\n\nDopo cinque anni, in 48 persone, chi aveva ricevuto l'impianto riferiva meno dolore e il tessuto riparato si era mantenuto più spesso alla risonanza. Lo studio guarda indietro nel tempo e riguarda un gruppo piccolo: mostra una differenza, non dimostra che l'impianto sia adatto a ogni persona, e questo impianto non fa parte della pratica abituale.\nFonte: PubMed, PMID 42965407."}};
var SOCV={"2": {"video": {"chir": ["Cartilagine a cinque anni (Arthroscopy, 2026): analisi retrospettiva di sottogruppo di uno studio di fase 3, che confronta staminali mesenchimali allogeniche da sangue cordonale con ialuronato e la microfrattura in ginocchia con artrosi Kellgren-Lawrence da uno a tre, 48 pazienti al controllo finale.", "Il dolore alla VAS è 23,4 contro 46,3 (p = 0,0019), il WOMAC 21,8 contro 37,7 (p = 0,016), l'IKDC 59,4 contro 46,5 (p = 0,014). La riparazione durevole alla risonanza è 62,5% contro 26,3%, con un odds ratio di 8,2 e un intervallo di confidenza al 95% da 1,6 a 42,5.", "Il limite: studio retrospettivo, numero per braccio non riportato, soglia di miglioramento minimo non significativa con p tra 0,074 e 0,123, e comparatore la microfrattura semplice, non la tecnica con membrana. Solo abstract, non è in PMC.\nFonte: PubMed, PMID 42965407."], "misto": ["Per i difetti di cartilagine nel ginocchio si è confrontato un impianto di cellule staminali prese da sangue del cordone ombelicale, insieme a un gel di ialuronato, con la microfrattura, in ginocchia con artrosi lieve o moderata. Hanno completato il controllo a cinque anni 48 pazienti.", "In quel periodo il dolore era più basso con le staminali, 23,4 contro 46,3 su una scala fino a cento, e anche i punteggi funzionali erano più favorevoli. Alla risonanza la cartilagine riparata si manteneva più spesso: 62,5% contro 26,3%, con un intervallo di incertezza molto largo.", "Il limite: è un'analisi retrospettiva di un sottogruppo, la differenza nella soglia di miglioramento minimo non è significativa e il confronto è con la microfrattura semplice. Mostra una differenza, non dimostra che valga per ogni paziente.\nFonte: PubMed, PMID 42965407."], "pazienti": ["Quando la cartilagine del ginocchio è rovinata, la microfrattura stimola il corpo a formare un nuovo tessuto di riparazione. Uno studio l'ha confrontata con un impianto di cellule staminali prese dal sangue del cordone ombelicale di donatori, insieme a un gel di acido ialuronico.", "Dopo cinque anni, in 48 persone, chi aveva ricevuto l'impianto riferiva meno dolore e aveva punteggi funzionali più alti. Alla risonanza il tessuto riparato si era mantenuto più spesso nel tempo, in circa sei persone su dieci contro circa una su quattro.", "Lo studio guarda indietro nel tempo e riguarda un gruppo piccolo: mostra una differenza, non dimostra che valga per ogni persona. Questo impianto non fa parte della pratica abituale, e la scelta del trattamento si decide con il chirurgo sul singolo caso.\nFonte: PubMed, PMID 42965407."]}, "linkedin": {"chir": ["Cartilagine a cinque anni (Arthroscopy, 2026): analisi retrospettiva di sottogruppo di uno studio di fase 3, staminali mesenchimali allogeniche da sangue cordonale con ialuronato contro microfrattura, 48 pazienti al controllo su 89 dello studio originale.", "VAS 23,4 contro 46,3 (p = 0,0019), WOMAC 21,8 contro 37,7 (p = 0,016), IKDC 59,4 contro 46,5 (p = 0,014). Riparazione durevole alla RM 62,5% contro 26,3%, OR 8,2 (IC 95% 1,6-42,5).", "Il limite: retrospettivo, numero per braccio non riportato, MCID non significativa (p da 0,074 a 0,123), MOCART medio senza differenza. Solo abstract.\nFonte: PubMed, PMID 42965407."], "misto": ["Cartilagine del ginocchio, cinque anni dopo: uno studio retrospettivo ha confrontato un impianto di staminali da sangue cordonale con ialuronato e la microfrattura in 48 pazienti con artrosi lieve o moderata.", "Con le staminali il dolore era più basso (VAS 23,4 contro 46,3) e il tessuto riparato si manteneva più spesso alla risonanza (62,5% contro 26,3%).", "Il limite: sottogruppo di uno studio più grande, numero per gruppo non riportato, soglia di miglioramento minimo non significativa.\nFonte: PubMed, PMID 42965407."], "pazienti": ["Cartilagine del ginocchio: uno studio ha confrontato dopo cinque anni la microfrattura con un impianto di cellule staminali del cordone ombelicale.", "In 48 persone, chi aveva l'impianto riferiva meno dolore e il tessuto riparato si era mantenuto più spesso alla risonanza.", "Lo studio guarda indietro nel tempo ed è piccolo: indica una differenza, non una regola.\nFonte: PubMed, PMID 42965407."]}, "instagram": {"chir": ["Cartilagine a 5 anni: staminali allogeniche con ialuronato contro microfrattura.", "VAS 23,4 contro 46,3 (p = 0,0019); riparazione durevole alla RM 62,5% contro 26,3%.", "Retrospettivo, 48 pazienti, MCID non significativa.\nFonte: PubMed, PMID 42965407."], "misto": ["Cartilagine del ginocchio a cinque anni: staminali da sangue cordonale contro microfrattura.", "Dolore più basso e riparazione più spesso conservata alla risonanza (62,5% contro 26,3%).", "Studio retrospettivo su 48 pazienti.\nFonte: PubMed, PMID 42965407."], "pazienti": ["Cartilagine del ginocchio: staminali del cordone ombelicale contro microfrattura.", "Dopo cinque anni meno dolore e tessuto riparato più spesso conservato.", "Studio piccolo che guarda indietro nel tempo.\nFonte: PubMed, PMID 42965407."]}, "reel": {"chir": ["Cartilagine, cinque anni.", "Staminali allogeniche contro microfrattura, 48 pazienti.", "Retrospettivo; riparazione durevole 62,5% contro 26,3%.\nFonte: PubMed, PMID 42965407."], "misto": ["Cartilagine del ginocchio.", "Staminali del cordone contro microfrattura, dopo cinque anni.", "Più riparazione conservata; studio retrospettivo.\nFonte: PubMed, PMID 42965407."], "pazienti": ["Cartilagine del ginocchio.", "Staminali del cordone ombelicale contro microfrattura.", "Dopo cinque anni più tessuto conservato; studio piccolo.\nFonte: PubMed, PMID 42965407."]}}};
var TAGS={"2": {"linkedin": "#Ortopedia #Cartilagine #Ginocchio", "instagram": "#ortopedia #ginocchio #cartilagine #microfrattura #staminali #chirurgiadelginocchio #artroscopia #medicinabasatasulleprove #ortopediaticino #ticino #salute", "kw": "cartilagine del ginocchio, microfrattura, cellule staminali, acido ialuronico, difetto di cartilagine, artrosi del ginocchio, chirurgia del ginocchio"}};
var NLB={"1": {"prof": ["Protesi con pianificazione AI e robot: taglia più accurata, nessuna differenza funzionale a sei mesi", "Coorte retrospettiva (J Orthop Surg Hong Kong, 2026; solo abstract): 56 coppie appaiate per propensity score. Taglia femorale corretta nel 75,0% contro 58,9% (p = 0,008), tibiale 82,1% contro 69,6% (p = 0,146); osteotomia più breve di 2,26 minuti e perdite ematiche postoperatorie minori di 123,6 mL. Dolore, mobilità e punteggio HSS senza differenze fino a sei mesi.", "Nota critica: retrospettivo, esito primario di processo; il robot e la protesi non sono nominati e il vantaggio tecnico non si traduce in funzione a sei mesi."], "mix": ["Protesi di ginocchio con pianificazione al computer e robot: più precisione, stessa funzione a sei mesi", "Uno studio retrospettivo cinese su 56 coppie di pazienti confronta la protesi totale con pianificazione assistita da intelligenza artificiale e robot e quella con tecnica tradizionale. La misura della componente femorale è più spesso corretta (75,0% contro 58,9%), l'intervento perde meno sangue e l'osteotomia è più breve; dolore, mobilità e punteggio funzionale a sei mesi non differiscono.", "Nota sul limite: studio retrospettivo di un solo gruppo, con follow-up breve; il tipo di robot non è indicato."], "paz": ["Protesi di ginocchio con computer e robot: più precisione, recupero simile dopo sei mesi", "Uno studio ha confrontato due modi di mettere la protesi al ginocchio: con pianificazione al computer e braccio robotico oppure con la tecnica abituale. Con il robot le misure dell'impianto erano più spesso esatte e si perdeva un po' meno sangue, ma dopo sei mesi dolore e movimento erano simili nei due gruppi.", "Nota rassicurante: la tecnica abituale ha dato risultati simili sulla funzione; il chirurgo sceglie in base al singolo caso."], "kw": "protesi totale di ginocchio, chirurgia robotica, pianificazione preoperatoria, intelligenza artificiale, ginocchio"}, "2": {"prof": ["Cartilagine a cinque anni: staminali allogeniche con ialuronato contro microfrattura, studio retrospettivo", "Analisi retrospettiva di sottogruppo di uno studio di fase 3 (Arthroscopy, 2026; solo abstract), ginocchia con artrosi Kellgren-Lawrence I-III, 48 pazienti al controllo a cinque anni: VAS 23,4 contro 46,3 (p = 0,0019), IKDC 59,4 contro 46,5 (p = 0,014); riparazione durevole alla RM 62,5% contro 26,3% (OR 8,2, IC 95% 1,6-42,5).", "Nota critica: retrospettivo, numero per braccio non riportato, soglia di miglioramento minimo non significativa, comparatore la microfrattura semplice."], "mix": ["Cartilagine del ginocchio: staminali da sangue cordonale contro microfrattura, a cinque anni", "Uno studio retrospettivo su 48 pazienti con artrosi lieve o moderata confronta, a cinque anni, la microfrattura con un impianto di staminali da sangue cordonale e ialuronato. Con l'impianto il dolore è più basso (VAS 23,4 contro 46,3) e la riparazione alla risonanza si mantiene più spesso (62,5% contro 26,3%).", "Nota sul limite: sottogruppo di uno studio più ampio, gruppi di numerosità non riportata, miglioramento minimo non significativo."], "paz": ["Cartilagine del ginocchio: un confronto a cinque anni fra due modi di ripararla", "Uno studio ha seguito per cinque anni persone con cartilagine danneggiata, trattate con microfrattura oppure con un impianto di cellule staminali del cordone ombelicale. Chi aveva l'impianto riferiva meno dolore e il tessuto riparato si era mantenuto più spesso.", "Nota rassicurante: lo studio è piccolo e guarda indietro nel tempo; indica una differenza ma questo impianto non fa parte della pratica abituale."], "kw": "cartilagine del ginocchio, microfrattura, cellule staminali, difetto di cartilagine, ginocchio"}, "3": {"prof": ["Tenodesi laterale MERI: striscia di fascia lata superficiale al collaterale, un'ancora, nessun dato", "Nota tecnica (Arthroscopy Techniques, 2026; testo completo letto): striscia di fascia lata di 1 cm e 6 cm di lunghezza, ancora a vite con quattro suture a 1 cm prossimale all'inserzione del legamento anterolaterale, chiusura della fascia sull'ancora; la striscia resta superficiale al collaterale laterale. Gli autori la dicono probabilmente meno restrittiva del Lemaire modificato.", "Nota critica: nessun paziente né dato biomeccanico; il confronto con altre tenodesi resta da fare; due autori dichiarano consulenze per aziende di dispositivi."], "mix": ["Crociato: una tenodesi laterale più semplice per controllare la rotazione, descritta ma non ancora studiata", "Una nota tecnica descrive un rinforzo sul lato esterno del ginocchio da associare alla ricostruzione del crociato, con una striscia di fascia della coscia di un centimetro e un'ancora. Passa sopra il legamento collaterale laterale e, per gli autori, trattiene la rotazione in modo meno rigido delle tecniche più estese.", "Nota sul limite: non ci sono pazienti né misure meccaniche; l'efficacia non è dimostrata."], "paz": ["Crociato: una tecnica descritta per limitare la rotazione del ginocchio", "Chirurghi francesi descrivono un piccolo rinforzo sul lato esterno del ginocchio da fare insieme alla ricostruzione del crociato. Serve a limitare la rotazione della tibia senza irrigidire troppo l'articolazione.", "Nota rassicurante: è una descrizione della tecnica e non uno studio sui pazienti; il chirurgo valuta caso per caso se serva."], "kw": "legamento crociato anteriore, tenodesi laterale, instabilità rotatoria, chirurgia del ginocchio"}, "4": {"prof": ["Allotrapianto meniscale: nessun vantaggio chiaro di una fissazione, estrusione maggiore con i soli tessuti molli", "Revisione sistematica (Arthroscopy, 2026; solo abstract): 27 articoli e 1622 allotrapianti, 1125 laterali e 80 mediali. Punteggi riferiti dai pazienti migliorati con ogni fissazione, nessun vantaggio chiaro di una tecnica per esiti o fallimento; l'estrusione sembra maggiore con la sola fissazione dei tessuti molli.", "Nota critica: pochi confronti diretti, pochissimi casi mediali; «nessuna differenza» non è prova di equivalenza."], "mix": ["Trapianto di menisco: la tecnica di fissazione sembra contare poco per i sintomi", "Una revisione di 27 studi su oltre milleseicento trapianti di menisco non trova una tecnica di fissazione chiaramente superiore per i punteggi dei pazienti o per il fallimento del trapianto. Il menisco sembra spostarsi di più verso l'esterno quando è fissato solo ai tessuti molli.", "Nota sul limite: pochi studi confrontano direttamente le tecniche e i casi del compartimento interno sono molto pochi."], "paz": ["Trapianto di menisco: come si fissa conta poco per come ti senti", "Una revisione di molti studi ha guardato i trapianti di menisco da donatore. Dopo l'intervento le persone stavano meglio con qualunque modo di fissarlo, e nessuno è risultato chiaramente migliore degli altri.", "Nota rassicurante: i dati sono pochi per alcune tecniche; il chirurgo sceglie quella che conosce meglio e che si adatta al caso."], "kw": "trapianto di menisco, allotrapianto meniscale, menisco, ginocchio"}, "5": {"prof": ["Osteotomia tibiale aperta: MPTA sotto 90° associato a restringimento dello spazio, soglia esplorativa", "Coorte retrospettiva (Knee Surg Relat Res, 2026): 133 ginocchia, controllo a tre anni; progressione dell'artrosi mediale nel 35,3%. Con MPTA postoperatorio inferiore a 90° OR 3,300 (IC 95% 1,327-8,198), 5,408 (IC 95% 1,400-20,905) nei ginocchi Kellgren-Lawrence 0-1.", "Nota critica: soglia ricavata dagli stessi dati, esito solo radiografico, nessuna validazione esterna."], "mix": ["Osteotomia della tibia: correggere abbastanza l'asse protegge lo spazio dell'articolazione", "In 133 ginocchia operate di osteotomia, quando l'angolo della tibia dopo l'intervento restava sotto 90 gradi lo spazio fra femore e tibia si riduceva più spesso nei tre anni successivi (odds ratio 3,3, intervallo di confidenza 1,3-8,2), soprattutto nei ginocchi senza artrosi alla radiografia.", "Nota sul limite: è un'associazione misurata solo con la radiografia, con una soglia ricavata dagli stessi dati."], "paz": ["Osteotomia della tibia: la correzione dell'asse conta per la durata dello spazio articolare", "Uno studio su 133 ginocchia operate per riallineare la gamba ha visto che, quando la correzione era più ampia, lo spazio fra le ossa del ginocchio si riduceva meno nei tre anni successivi, soprattutto quando l'artrosi non era ancora visibile alla radiografia.", "Nota rassicurante: è uno studio sulle radiografie e non sui sintomi; il chirurgo decide la correzione dopo misure precise."], "kw": "osteotomia tibiale alta, ginocchio varo, artrosi del ginocchio, riallineamento"}, "6": {"prof": ["Lesioni multilegamentose: classificazioni attuali non validate per la prognosi, serve un sistema nuovo", "Revisione narrativa (J Clin Orthop Trauma, 2026): i sistemi più usati derivano dalla classificazione della lussazione di ginocchio (Kennedy, Schenck) e descrivono l'anatomia legamentosa; quelli recenti includono meccanismo e patologia periarticolare ma sono poco usati.", "Nota critica: narrativa, senza numeri né metodo di selezione; non dice quanto una classificazione preveda l'esito."], "mix": ["Lesioni di più legamenti del ginocchio: le classificazioni usate oggi descrivono, non prevedono", "Una revisione degli schemi con cui si classificano le lesioni di più legamenti del ginocchio osserva che i più usati descrivono soprattutto quali legamenti sono lesi. Gli autori chiedono un sistema che tenga conto anche del meccanismo, delle lesioni intorno all'articolazione, dei vasi e dei nervi.", "Nota sul limite: è una revisione senza dati e senza metodo di selezione degli studi."], "paz": ["Lesioni di più legamenti del ginocchio: i medici cercano un modo migliore di classificarle", "Quando si lesionano più legamenti del ginocchio insieme, i medici usano schemi per descrivere il danno. Una revisione osserva che questi schemi non dicono ancora bene come andrà il recupero.", "Nota rassicurante: serve solo a migliorare il linguaggio fra medici; il trattamento si decide sul singolo caso."], "kw": "lesioni multilegamentose, lussazione del ginocchio, classificazione, legamenti del ginocchio"}, "7": {"prof": ["Crociato nella NFL: ritorno al gioco nel 75,5%, prestazione ridotta per due anni", "Serie di casi retrospettiva (Arthrosc Sports Med Rehabil, 2026): 237 giocatori operati di LCA fra 2017 e 2024. Ritorno al gioco 75,5% (IC 95% 69,7-80,6, Wilson, calcolo mio), ritorno alla prestazione nel 51% di chi era tornato; PAR ridotto al primo (p = 0,002) e al secondo anno (p = 0,004).", "Nota critica: livello IV, nessun controllo, innesto e tecnica non riportati, atleti professionisti."], "mix": ["Crociato negli atleti professionisti: tre su quattro tornano a giocare, la prestazione cala per due anni", "Uno studio su 237 giocatori della lega americana di football operati di legamento crociato mostra che il 75,5% è tornato a giocare e che circa metà di questi ha ritrovato oltre il 90% della prestazione precedente. Nei due anni successivi il rendimento complessivo è più basso, soprattutto nella corsa e nella copertura.", "Nota sul limite: dati pubblici di atleti d'élite, senza gruppo di controllo e senza informazioni sulla tecnica chirurgica."], "paz": ["Crociato: anche nei professionisti il ritorno al livello di prima non è scontato", "Uno studio su giocatori professionisti di football americano operati al legamento crociato ha visto che la maggior parte è tornata a giocare, ma non tutti hanno ritrovato lo stesso rendimento di prima nei due anni seguenti.", "Nota rassicurante: riguarda atleti d'élite con carichi molto diversi da quelli di un paziente comune; il percorso di recupero è personale."], "kw": "legamento crociato anteriore, ritorno allo sport, atleti professionisti, ginocchio"}};
var ARTICLES=[{n:1,mono:'m-gray',dot:'orange',sec:'res',j:'J Orthop Surg (Hong Kong)',h:'Protesi con pianificazione AI e robot: più precisione tecnica, nessun vantaggio funzionale a sei mesi',v:'Coorte retrospettiva su 144 pazienti con protesi totale primaria (69 con pianificazione AI e robot, 75 convenzionali), 56 coppie appaiate per propensity score. Taglia femorale giusta nel 75,0% contro 58,9% (p = 0,008), tibiale 82,1% contro 69,6% (p = 0,146); osteotomia più breve di 2,26 minuti (IC 95% da -3,98 a -0,55) e perdita ematica postoperatoria totale minore di 123,6 mL (IC 95% da -221,1 a -26,1). Dolore, mobilità e punteggio HSS non differiscono fino a sei mesi.',ax:'Zhang, Hu, Fan, Sun, Wang, Song, Yao',date:'ott 2026',meta:'coorte retrospettiva, 144 pazienti (56 coppie), livello non riportato, solo abstract',pmid:'42961828',doi:'10.1177/10225536261504098',journal:'Journal of orthopaedic surgery (Hong Kong)',authors:'Zhang T, Hu Y, Fan Y, Sun Z, Wang J, Song H, Yao Q',design:'Coorte retrospettiva (Beijing Shijitan Hospital), appaiamento 1:1 per propensity score su otto covariate, t-test appaiati e test di McNemar, regressione doppiamente robusta come analisi di sensibilità. Esito primario: accuratezza della taglia prevista della protesi; secondari: tempo di osteotomia, perdite ematiche, allineamento radiografico, VAS, mobilità e punteggio HSS. Robot, protesi e software di pianificazione non sono nominati nell\'abstract. Solo abstract: non è in PMC.',pop:'144 pazienti con protesi totale primaria monolaterale (69 AI-robot, 75 convenzionale), 56 coppie dopo l\'appaiamento con differenze standardizzate sotto 0,1. Età, sesso e BMI non riportati nell\'abstract; esiti funzionali fino a sei mesi.',results:'Taglia femorale corretta 75,0% contro 58,9% (p = 0,008); tibiale 82,1% contro 69,6% (p = 0,146). Tempo di osteotomia -2,26 min (IC 95% da -3,98 a -0,55; p = 0,011); perdita ematica intraoperatoria -27,4 mL (IC 95% da -48,2 a -6,5) e postoperatoria totale -123,6 mL (IC 95% da -221,1 a -26,1). Angolo laterale della componente tibiale +0,76° (IC 95% da 0,11 a 1,41; p = 0,022); gli altri parametri radiografici non differiscono. VAS, mobilità e HSS senza differenze significative a nessun controllo fino a sei mesi (valori non riportati).',concl:'Gli autori: il valore della tecnologia integrata sta nell\'ottimizzare l\'esecuzione tecnica, non nell\'accelerare il recupero funzionale a breve termine.',limits:'Retrospettivo e non randomizzato: l\'appaiamento bilancia le otto covariate misurate, non quelle non misurate · L\'esito primario è di processo (taglia prevista), non clinico, e il vantaggio tecnico non si traduce in punteggi diversi a sei mesi · Robot, protesi e allineamento obiettivo non nominati; follow-up di sei mesi; un solo gruppo di lavoro',perte:'Arancione: mette in discussione il valore clinico del robot, e quindi anche del tuo VELYS, ma solo in modo indiretto. Il sistema non è nominato e il lavoro viene da un solo gruppo cinese: non è trasferibile al VELYS. Dice una cosa utile da avere pronta in ambulatorio: più precisione tecnica e meno sanguinamento non diventano una funzione più alta a sei mesi, in linea con l\'RCT RACER-Knee (Lancet, agosto; sistema Mako, non VELYS) e con l\'editoriale uscito oggi sullo stesso trial. Cosa fare: nulla da cambiare in sala; con i pazienti parla di precisione dell\'impianto, non di recupero più rapido. Non muove nessuna tensione aperta.'},{n:2,mono:'m-gray',dot:'green',sec:'res',j:'Arthroscopy',h:'Cartilagine: staminali allogeniche con ialuronato contro microfrattura a cinque anni, analisi retrospettiva',v:'Analisi retrospettiva di sottogruppo di uno studio di fase 3 in ginocchia con artrosi Kellgren-Lawrence I-III: degli 89 pazienti originali 64 sono inclusi e 48 hanno il controllo a cinque anni. Con le staminali contro la microfrattura VAS 23,4 contro 46,3 (p = 0,0019), WOMAC 21,8 contro 37,7 (p = 0,016), IKDC 59,4 contro 46,5 (p = 0,014); la soglia di miglioramento minimo non è significativa. Riparazione durevole alla RM 62,5% contro 26,3% (p = 0,031; OR 8,2, IC 95% 1,6-42,5).',ax:'Park, Ha',date:'ott 2026',meta:'analisi retrospettiva di sottogruppo di studio di fase 3, 48 pazienti a 5 anni, livello III, solo abstract',pmid:'42965407',doi:'10.1002/arj.70706',journal:'Arthroscopy',authors:'Park YB, Ha CW',design:'Analisi retrospettiva di sottogruppo di uno studio di fase 3 (livello III dichiarato): impianto allogenico di cellule staminali mesenchimali da sangue cordonale e ialuronato (UCB-MSCs-HA) contro microfrattura, in ginocchia con artrosi Kellgren-Lawrence I-III. Esiti: VAS, WOMAC, IKDC, soglia di miglioramento minimo clinicamente importante (MCID) e punteggio MOCART alla RM a 3 e 5 anni; riparazione durevole definita come MOCART superiore a 60 a entrambi i controlli con variazione inferiore a 10 punti. Solo abstract: non è in PMC.',pop:'Degli 89 pazienti dello studio originale 64 sono stati inclusi e 48 hanno completato i cinque anni; ripartizione per braccio, età, sesso, BMI e dimensione dei difetti non riportate nell\'abstract. Il prodotto impiantato non è nominato.',results:'Valori medi (tra parentesi l\'intervallo riportato) UCB-MSCs-HA contro microfrattura a 5 anni. VAS 23,4 (0-69) contro 46,3 (7-90), p = 0,0019. WOMAC 21,8 (0-70) contro 37,7 (3-79), p = 0,016. IKDC 59,4 (20,7-95,4) contro 46,5 (13,8-75,9), p = 0,014. MCID raggiunta, non significativa: VAS 50,0% contro 28,1% (p = 0,123), WOMAC 53,1% contro 28,1% (p = 0,074), IKDC 56,3% contro 31,3% (p = 0,077). MOCART senza differenza fra i gruppi. Riparazione durevole 62,5% contro 26,3% (p = 0,031); unico fattore associato l\'impianto di staminali (OR 8,2; IC 95% 1,6-42,5; p = 0,012). Allineamento dell\'arto non associato agli esiti.',concl:'Gli autori: l\'impianto allogenico di staminali e ialuronato ha dato esiti clinici più favorevoli e una quota maggiore di riparazione durevole alla RM a cinque anni rispetto alla microfrattura.',limits:'Retrospettivo, sottogruppo di uno studio di fase 3: solo 48 su 89 pazienti arrivano ai cinque anni e il numero per braccio non è riportato · Sulla soglia di miglioramento minimo le differenze non sono significative e il MOCART medio non differisce fra i gruppi · L\'OR della riparazione durevole ha un intervallo molto largo (1,6-42,5); prodotto, finanziamento e conflitti di interesse non riportati nell\'abstract',perte:'Verde: riguarda la tua area cartilagine, non la tua tecnica. Il comparatore è la microfrattura semplice, mentre tu usi AMIC (microfrattura con membrana Chondro-Gide) e AutoCart; il prodotto è allogenico, non autologo, e la popolazione ha artrosi Kellgren-Lawrence I-III, più avanzata di un difetto focale. Non è quindi un confronto con la tua filiera. Dice però che la microfrattura semplice, che resta il termine di paragone, perde terreno a cinque anni anche contro un\'alternativa non autologa. Cosa fare: nulla da cambiare; l\'alternativa non è disponibile né trasferibile alla tua pratica. Non muove T5 (variabilità del tessuto nel minced cartilage), ma ricorda quanto pesi il comparatore scelto.'},{n:3,mono:'m-gray',dot:'green',sec:'res',j:'Arthrosc Tech',h:'LET semplificato MERI: striscia di fascia lata, un\'ancora, passaggio superficiale al collaterale',v:'Nota tecnica senza pazienti (testo completo letto): striscia di fascia lata larga 1 cm e lunga 6 cm, un\'ancora metallica a vite con quattro suture a 1 cm prossimale all\'inserzione del legamento anterolaterale, sutura continua e chiusura della fascia sull\'ancora. La striscia resta volutamente superficiale al collaterale laterale; gli autori la dicono probabilmente meno restrittiva del Lemaire modificato, senza dati.',ax:'Bouguennec, Colombet, Graveleau',date:'ott 2026',meta:'nota tecnica, nessun paziente, testo completo letto (PMC)',pmid:'42964504',doi:'10.1002/atn2.70325',journal:'Arthroscopy techniques',authors:'Bouguennec N, Colombet P, Graveleau N',design:'Nota tecnica con video (Sports Clinic of Bordeaux-Merignac). Descrive la tenodesi laterale MERI (Minimizing Excessive Rotational Instability) associata alla ricostruzione del LCA, che ricostruisce fibre di Kaplan distali, cinghia condilare e inserzione femorale del legamento anterolaterale. Testo completo letto su PMC. Nessun paziente, nessun esito, nessuno studio biomeccanico.',pop:'Nessuna. Il lavoro non riporta pazienti. Non è indicata per instabilità laterale globale né per lesioni complesse dell\'angolo posterolaterale.',results:'Nessun dato originale. Dimensioni dell\'effetto e intervalli di confidenza non riportati. Gli autori stessi scrivono che il controllo di rotazione non è stato valutato in studi biomeccanici e che l\'efficacia clinica rispetto alle tenodesi consolidate resta da confermare.',concl:'Gli autori: tecnica semplice, economica e poco invasiva, un\'alternativa per pazienti selezionati con instabilità anterolaterale, probabilmente meno restrittiva del Lemaire modificato.',limits:'Nessun paziente e nessun dato biomeccanico: non si sa quanta rotazione controlli · Per scelta meno restrittiva delle tenodesi profonde al collaterale: gli autori ammettono possibile lassità residua nelle instabilità gravi · Due autori dichiarano consulenze per aziende di dispositivi (fra cui Stryker e Arthrex) e finanziamenti da SBM; l\'ancora descritta è un prodotto Smith & Nephew',perte:'Verde: riguarda il tuo LET su tutti. È una striscia di fascia lata (stessa famiglia del tuo innesto ileotibiale) che passa superficiale al collaterale laterale come il tuo Lemaire modificato, ma con un\'ancora a vite e suture continue invece dell\'onlay, e gli autori la dicono probabilmente meno restrittiva proprio del Lemaire modificato. Nessun paziente, nessun confronto: affianca un\'altra variante superficiale senza chiudere T2. Cosa fare: nulla da cambiare; se in perizia o a un convegno ti citano questa tecnica, dì che esiste solo come descrizione, senza dati biomeccanici né clinici.'},{n:4,mono:'m-gray',dot:'green',sec:'res',j:'Arthroscopy',h:'Allotrapianto meniscale: nessun vantaggio chiaro di una tecnica di fissazione, ma pochi confronti diretti',v:'Revisione sistematica di 27 articoli e 1622 allotrapianti meniscali (1125 laterali, 80 mediali, 417 senza compartimento indicato): i punteggi riferiti dai pazienti migliorano con qualunque fissazione e non emerge un vantaggio chiaro di una tecnica per esiti o fallimento del trapianto. L\'estrusione sembra maggiore con la sola fissazione dei tessuti molli. Pochi studi confrontano direttamente le tecniche.',ax:'Miltenberg, Davis, Fellheimer, Tjoumakaris, Johns, Roslund, Freedman',date:'ott 2026',meta:'revisione sistematica, 27 studi, 1622 trapianti, livello III, solo abstract',pmid:'42928052',doi:'10.1002/arj.70667',journal:'Arthroscopy',authors:'Miltenberg B, Davis G, Fellheimer HS, Tjoumakaris P, Johns WL, Roslund C, Freedman KB',design:'Revisione sistematica (PubMed, Scopus, Embase) di studi di livello II e III (livello III dichiarato) sulle tecniche di fissazione dell\'allotrapianto meniscale mediale e laterale, con analisi per sottogruppi mediale e laterale. Esiti: punteggi riferiti dai pazienti, estrusione meniscale, fallimento del trapianto. Solo abstract: non è in PMC.',pop:'27 articoli, 1622 allotrapianti (1125 laterali, 80 mediali, 417 con compartimento non specificato). Età, follow-up e tecniche per studio non riportati nell\'abstract.',results:'L\'allotrapianto si associa a punteggi riferiti dai pazienti migliorati con qualunque fissazione; nessun vantaggio chiaro di una tecnica né per i punteggi né per il fallimento; estrusione maggiore con la sola fissazione dei tessuti molli. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'Gli autori: i chirurghi possono scegliere la fissazione in base alle procedure associate e alla familiarità tecnica; mancano confronti comparativi di qualità.',limits:'Solo 80 casi mediali contro 1125 laterali: il risultato mediale poggia su pochissimi dati · Pochi studi confrontano direttamente le fissazioni, quindi «nessuna differenza» non è prova di equivalenza · Studi di livello II e III con tecniche, indicazioni e follow-up eterogenei',perte:'Verde: l\'allotrapianto meniscale rientra nella tua chirurgia meniscale, anche se non è fra i gesti che descrivi di eseguire di routine. È un lavoro che toglie importanza alla scelta della fissazione per gli esiti riferiti dai pazienti e la sposta su un dato di imaging, l\'estrusione, che nella radice meniscale è già al centro di T3. Cosa fare: se ti capita un trapianto, scegli la fissazione che padroneggi; tieni conto che la sola fissazione dei tessuti molli sembra estrudere di più. Non muove T3, che riguarda la radice e non l\'allotrapianto.'},{n:5,mono:'m-gray',dot:'green',sec:'res',j:'Knee Surg Relat Res',h:'Osteotomia tibiale aperta: un MPTA postoperatorio sotto 90° si associa al restringimento dello spazio',v:'Coorte retrospettiva su 133 ginocchia (101 pazienti) con osteotomia tibiale alta aperta mediale e controllo a tre anni: 47 pazienti (35,3%) mostrano progressione dell\'artrosi mediale. Con MPTA postoperatorio inferiore a 90° l\'odds ratio di progressione è 3,300 (IC 95% 1,327-8,198; p = 0,010), 5,408 (IC 95% 1,400-20,905) nei ginocchi con Kellgren-Lawrence 0-1. La soglia di 90° viene dalla curva ROC degli stessi dati.',ax:'Chiba, Maeda, Sasaki, Tsushima, Kimura, Tsuda, Ishibashi',date:'ott 2026',meta:'coorte retrospettiva, 133 ginocchia, livello III, testo in PMC non letto',pmid:'42958464',doi:'10.1186/s43019-026-00338-0',journal:'Knee surgery & related research',authors:'Chiba D, Maeda S, Sasaki E, Tsushima T, Kimura Y, Tsuda E, Ishibashi Y',design:'Coorte retrospettiva (livello III dichiarato) su osteotomia tibiale alta aperta mediale (MOWHTO). Esiti: variazione della larghezza dello spazio articolare mediale e laterale e dell\'area degli osteofiti su radiografia semplice dal postoperatorio ai tre anni; progressione definita da una riduzione dello spazio mediale di almeno 0,3 mm; equazioni di stima generalizzate. Nessun esito clinico nell\'abstract. Ha un PMC ID ma non è stato letto per intero.',pop:'133 ginocchia di 101 pazienti (58 donne), età media 57,5 ± 7,9 anni, BMI 26,3 ± 4,0; 32 pazienti operati bilateralmente. Follow-up a tre anni.',results:'Progressione dell\'artrosi mediale in 47 pazienti (35,3%). Sia MPTA postoperatorio sia sua variazione correlano con la variazione dello spazio mediale; soglia di MPTA 90° dalla curva ROC. Correzione inferiore a 90°: OR 3,300 (IC 95% 1,327-8,198; p = 0,010) rispetto a 90° o più; con Kellgren-Lawrence 0 o 1 OR 5,408 (IC 95% 1,400-20,905; p = 0,014). Lo spazio laterale non correla con MPTA; gli osteofiti aumentano ma senza correlazione.',concl:'Gli autori: solo nei ginocchi senza artrosi radiografica, una correzione dell\'MPTA inferiore a 90° si associa a maggiore probabilità di restringimento dello spazio mediale a breve termine.',limits:'Retrospettivo: soglia di 90° ricavata dagli stessi dati con la curva ROC, senza validazione esterna · Esito solo radiografico (spazio articolare), nessun punteggio clinico né revisione in artroprotesi · Effetto presente solo nei ginocchi Kellgren-Lawrence 0-1; slope e rotazione non considerati nell\'abstract',perte:'Verde: osteotomia, una tua area. La domanda pratica è quanto correggere: qui una correzione che porta l\'MPTA a 90° o più si associa a meno restringimento dello spazio mediale a tre anni, ma soltanto nei ginocchi senza artrosi radiografica, con soglia esplorativa e senza esiti clinici. Cosa fare: usala come argomento per il margine di correzione nella pianificazione di un varo con cartilagine ancora conservata, non come soglia da applicare a tutti. Non è un lavoro sul tuo slope: l\'osteotomia di slope resta fuori da questo dato.'},{n:6,mono:'m-gray',dot:'green',sec:'res',j:'J Clin Orthop Trauma',h:'Lesioni multilegamentose: le classificazioni in uso non sono validate per la prognosi, serve un sistema nuovo',v:'Revisione narrativa (ricerca mirata su PubMed) delle classificazioni delle lesioni multilegamentose del ginocchio: i sistemi più usati derivano da quelli della lussazione di ginocchio (Kennedy, Schenck) e descrivono soprattutto l\'anatomia legamentosa. Quelli più recenti includono meccanismo e patologia periarticolare ma sono poco usati. Per gli autori serve un sistema aggiornato, da validare prima che guidi prognosi o trattamento.',ax:'Domonoske, Vandamme, Hunter, McGrale, Klasan, Ernat',date:'ott 2026',meta:'revisione narrativa, nessun numero nell\'abstract, livello basso, testo in PMC non letto',pmid:'42964820',doi:'10.1016/j.jcot.2026.103641',journal:'Journal of clinical orthopaedics and trauma',authors:'Domonoske RW, Vandamme EM, Hunter CD, McGrale C, Klasan A, Ernat JJ',design:'Revisione narrativa con ricerca mirata su PubMed/MEDLINE (lesioni multilegamentose, lussazione di ginocchio, sistemi di classificazione, meccanismo, lesioni neurovascolari, patologia periarticolare, esiti). Nessun criterio di selezione degli studi e nessuna sintesi quantitativa nell\'abstract. Ha un PMC ID ma non è stato letto per intero.',pop:'Nessuna. Il lavoro non riporta pazienti né numero di studi.',results:'Nessun dato quantitativo. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'Gli autori: i sistemi anatomici restano utili per descrivere e per la ricerca, ma la letteratura sostiene la necessità di un sistema aggiornato che integri meccanismo, lesioni periarticolari e neurovascolari, compromissione dei tessuti molli; serve validazione prima di usarlo per prognosi o trattamento.',limits:'Revisione narrativa senza metodo di selezione dichiarato: l\'elenco dei sistemi non è sistematico · Nessun numero sul legame fra classificazione ed esito, che è proprio ciò che il titolo giudica · Nessuna indicazione su quali lesioni (LCP, angolo posterolaterale, collaterale mediale) pesino di più',perte:'Verde: riguarda le tue multilegamentose (LCP, angolo posterolaterale, collaterale mediale). Non cambia nulla in sala. Cosa fare: nei tuoi referti e nelle perizie descrivi la lesione con la classificazione anatomica abituale e aggiungi in chiaro meccanismo, lesioni periarticolari e stato neurovascolare, i campi che gli autori chiedono a un sistema futuro (suggerimento mio, non loro). Nessuna tensione toccata.'},{n:7,mono:'m-gray',dot:'gray',sec:'res',j:'Arthrosc Sports Med Rehabil',h:'LCA nella NFL: tre su quattro tornano a giocare, la prestazione cala nei due anni successivi',v:'Serie di casi retrospettiva su 237 giocatori della NFL operati di LCA fra 2017 e 2024: il 75,5% torna a giocare (IC 95% 69,7-80,6, Wilson, calcolo mio), il 51% di chi è tornato supera il 90% della prestazione precedente. Il punteggio PAR cala al primo (p = 0,002) e al secondo anno (p = 0,004), per corsa e copertura. Innesto e tecnica non sono riportati.',ax:'Hayes, Kerhoulas, Matache, Pickell',date:'ott 2026',meta:'serie di casi retrospettiva, 237 giocatori, livello IV, testo in PMC non letto',pmid:'42953817',doi:'10.1002/ars2.70117',journal:'Arthroscopy, sports medicine, and rehabilitation',authors:'Hayes E, Kerhoulas Z, Matache B, Pickell M',design:'Serie di casi retrospettiva (livello IV dichiarato) su giocatori della NFL sottoposti a ricostruzione del LCA fra il 2017 e il 2024, identificati da database pubblici e rapporti di infortunio; dati da un anno prima a due anni dopo l\'infortunio. Ritorno al gioco: attivo in una partita di stagione regolare; ritorno alla prestazione: oltre il 90% della prestazione precedente; esito di prestazione: punti sopra la sostituzione (PAR, Sports Information Solutions); regressione logistica binaria e test appaiati. Ha un PMC ID ma non è stato letto per intero.',pop:'237 giocatori nell\'analisi del ritorno al gioco, 173 in quella del ritorno alla prestazione. Età, posizione, innesto e tecnica non riportati nell\'abstract.',results:'Ritorno al gioco 75,5% (circa 179 su 237; IC 95% 69,7-80,6, Wilson, calcolo mio); ritorno alla prestazione 51% di chi era tornato. Più partite prima dell\'infortunio, titolarità e PAR alto predicono il ritorno al gioco (p = 0,03; p < 0,001; p < 0,001); età più giovane e PAR basso predicono il ritorno alla prestazione (p = 0,004; p < 0,001). PAR totale ridotto al primo (p = 0,002) e al secondo anno (p = 0,004), per corsa (p = 0,02; p = 0,001) e copertura (p = 0,003; p = 0,03).',concl:'Gli autori: dopo il LCA i giocatori NFL con più partite e prestazione precedente più alta tornano più spesso a giocare, i più giovani con prestazione precedente più bassa tornano più spesso alla prestazione, e la prestazione cala per due anni.',limits:'Serie di casi senza gruppo di controllo e con dati pubblici: non separa l\'effetto dell\'intervento da quello dell\'infortunio e della carriera · Innesto, tecnica, rinforzo laterale e riabilitazione non riportati · Popolazione di atleti professionisti di alto livello, non trasferibile al paziente comune',perte:'Bianco: nel perimetro ma non tocca la tua pratica. Non è un\'indicazione sul criterio di rientro (T4): qui «tornare» significa essere attivo in una partita, non rispettare una soglia funzionale. Il dato utile per un paziente sportivo è che anche in atleti professionisti il ritorno alla prestazione precedente non è la regola. Cosa fare: nulla.'}];
var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Domenica primo novembre, e la domenica si apre con la settimana. Dal venticinque al trentuno ottobre i lavori che contano sono quattro. Il ventotto, uno studio di cadavere dello Steadman Philippon: il punto femorale e l'angolo di fissazione del LET non cambiano il carico sul trapianto. Il ventinove, una metanalisi su venticinque studi: la prontezza psicologica distingue chi rientra allo sport al livello di prima, ma non sposta la soglia del novanta per cento sul tuo innesto. Il trenta, una revisione sistematica sul tendine quadricipitale solo molle contro quello con blocco osseo, che è il tuo innesto: nessuna differenza significativa in nessuno dei cinque studi; e una revisione sulla centralizzazione della radice, che sposta la domanda senza chiuderla. Il trentuno, la coorte sulla sutura della radice: la frattura subcondrale preoperatoria si associa a meno miglioramenti e più reinterventi, più un editoriale sullo slope alto che mette in dubbio il LET da solo. La radice meniscale ha guadagnato un fattore prognostico, il LET qualche variante di costrutto senza dati; nessuna tensione si è chiusa.\n\nOggi sette lavori, nessuna scheda rossa e una arancione. Nessun richiamo di dispositivi nuovo, nessuna linea guida o consensus nuovo sulla tua pratica e nessuna ritrattazione che ti riguardi. Il raccoglitore è quello del trentuno ottobre, con tutte le fonti in ordine. La scheda arancione è una coorte retrospettiva cinese sulla protesi totale con pianificazione assistita da intelligenza artificiale e robot, di cui l'abstract non nomina il sistema: cinquantasei coppie appaiate. La taglia femorale è giusta nel settantacinque per cento contro il cinquantotto virgola nove, con p zero virgola zero zero otto; la tibiale non raggiunge la significatività. Meno sangue e osteotomia più breve di circa due minuti, ma nessuna differenza di dolore, mobilità e punteggio HSS a sei mesi. Non è trasferibile al VELYS ed è coerente con il trial RACER-Knee su Mako, che oggi ha anche un editoriale. Il lavoro del giorno è su Arthroscopy, sulla cartilagine: staminali allogeniche da sangue cordonale con ialuronato contro microfrattura, analisi retrospettiva di un sottogruppo di uno studio di fase tre, in ginocchia con artrosi lieve o moderata. A cinque anni sono arrivati quarantotto pazienti su ottantanove: dolore e punteggi funzionali più favorevoli con le staminali, ma la soglia di miglioramento minimo non è significativa; la riparazione durevole alla risonanza è sessantadue virgola cinque per cento contro ventisei virgola tre, con odds ratio otto virgola due e intervallo di confidenza da uno virgola sei a quarantadue virgola cinque. Il comparatore è la microfrattura semplice, non la tua AMIC, e il prodotto non è autologo. Poi una nota tecnica sul LET, chiamata MERI, di cui ho letto il testo completo: striscia di fascia lata di un centimetro, un'ancora, passaggio superficiale al collaterale laterale come il tuo; gli autori la dicono probabilmente meno restrittiva del Lemaire modificato, ma non ci sono pazienti né dati biomeccanici. Poi una revisione sistematica sull'allotrapianto meniscale: ventisette studi, nessun vantaggio chiaro di una fissazione, con l'estrusione che sembra maggiore con i soli tessuti molli. Sull'osteotomia tibiale alta aperta, centotrentatré ginocchia: un angolo tibiale mediale postoperatorio sotto i novanta gradi si associa al restringimento dello spazio, odds ratio tre virgola tre con intervallo da uno virgola tre a otto virgola due, e solo nei ginocchi senza artrosi radiografica. Una revisione narrativa sulle classificazioni delle lesioni multilegamentose chiede un sistema nuovo. In coda, i giocatori della NFL dopo il crociato: il settantacinque virgola cinque per cento torna a giocare e la prestazione cala per due anni. Nessuna tensione si chiude oggi; la seconda, sul tuo costrutto, ha una variante superficiale in più.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Domenica primo novembre, e la domenica si apre con la settimana. Quattro lavori contano, dal venticinque al trentuno ottobre."}, {"chi": "B", "t": "Quali, e che cosa cambiano per il mio crociato?"}, {"chi": "A", "t": "Il ventotto, il cadavere dello Steadman Philippon: punto femorale e angolo del LET non cambiano il carico sul trapianto. Il trenta, la revisione sul quadricipite solo molle, il tuo innesto: nessuna differenza significativa. Il trentuno, la coorte sulla radice meniscale: la frattura subcondrale peggiora l'esito."}, {"chi": "B", "t": "E le tensioni?"}, {"chi": "A", "t": "La radice ha un fattore prognostico in più, il LET qualche variante di costrutto senza dati. Nessuna si è chiusa."}, {"chi": "B", "t": "Passiamo a oggi. Quante schede, e di che colore?"}, {"chi": "A", "t": "Sette lavori, nessuna rossa e una arancione. Nessun richiamo nuovo, nessuna consensus sulla tua pratica, nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "L'arancione?"}, {"chi": "A", "t": "Una coorte cinese sulla protesi totale con pianificazione AI e robot, sistema non nominato. Taglia femorale giusta nel settantacinque per cento contro il cinquantotto virgola nove, ma nessuna differenza di dolore e funzione a sei mesi."}, {"chi": "B", "t": "Quindi per la mia VELYS non cambia niente."}, {"chi": "A", "t": "Non è trasferibile al VELYS, ed è coerente con il RACER-Knee su Mako. Parla di precisione dell'impianto, non di recupero più rapido."}, {"chi": "B", "t": "E il lavoro del giorno?"}, {"chi": "A", "t": "Cartilagine, su Arthroscopy: staminali allogeniche con ialuronato contro microfrattura, a cinque anni, in quarantotto pazienti. Riparazione durevole alla risonanza sessantadue virgola cinque contro ventisei virgola tre, ma con un intervallo larghissimo."}, {"chi": "B", "t": "Contro la microfrattura semplice, non contro la mia AMIC."}, {"chi": "A", "t": "Esatto, ed è retrospettivo. Poi la nota tecnica MERI sul LET, passaggio superficiale come il tuo, nessun paziente. Nessuna tensione si chiude oggi."}];
